const raw = ($input.first().json.SPEC_JSON || '').trim();
if (!raw) return [{ json: { SPEC: null, SPEC_JSON: '' } }];
let spec;
try { spec = JSON.parse(raw); } catch (e) { throw new Error('SPEC_JSON parameter is invalid JSON: ' + e.message); }

const fail = (msg) => { throw new Error('content spec invalid: ' + msg); };
if (typeof spec.title !== 'string' || !spec.title.trim()) fail('missing field: title');
if (!Array.isArray(spec.blocks) || spec.blocks.length < 3 || spec.blocks.length > 6)
  fail('blocks must be an array of 3 to 6 entries');
spec.blocks.forEach((b, i) => {
  if (!b || typeof b.label !== 'string' || !b.label.trim()) fail('missing field: blocks[' + i + '].label');
  if (b.value == null || String(b.value).trim() === '') fail('missing field: blocks[' + i + '].value');
});
if (typeof spec.accent !== 'string' || !/^#[0-9a-fA-F]{6}$/.test(spec.accent))
  fail('missing field: accent');
if (!spec.motion || typeof spec.motion !== 'object') fail('missing field: motion');
if (!['rise', 'fade', 'sweep', 'pulse'].includes(spec.motion.kind)) fail('missing field: motion.kind');
const d = Number(spec.motion.durationMs);
if (!Number.isFinite(d) || d < 2000 || d > 4000) fail('missing field: motion.durationMs');
if (typeof spec.alt !== 'string' || !spec.alt.trim()) fail('missing field: alt');
return [{ json: { SPEC: spec, SPEC_JSON: JSON.stringify(spec) } }];

const raw0 = $('author_spec').first().json.text || '';
