if (!spec.motion || typeof spec.motion !== 'object') fail('missing field: motion');
if (!['rise', 'fade', 'sweep', 'pulse'].includes(spec.motion.kind)) fail('missing field: motion.kind');
const d = Number(spec.motion.durationMs);
if (!Number.isFinite(d) || d < 2000 || d > 4000) fail('missing field: motion.durationMs');
if (typeof spec.alt !== 'string' || !spec.alt.trim()) fail('missing field: alt');
return [{ json: { SPEC: spec, SPEC_JSON: JSON.stringify(spec) } }];

const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const escAttr = (s) => esc(s).replace(/"/g, "&quot;");
function buildMarkup(tmpl, spec, fps, frames, viewport, isSvg) {
  const accent = /^#[0-9a-fA-F]{6}$/.test(spec.accent || "") ? spec.accent : "#22d3ee";
  const kind = ["rise", "fade", "sweep", "pulse"].includes(spec.motion && spec.motion.kind)
    ? spec.motion.kind : "rise";
  const duration = Math.max(1000, Math.min(4000, (spec.motion && spec.motion.durationMs) || 3000));
  const blocks = (spec.blocks || []).slice(0, 6);
  const step = Math.floor(duration / (blocks.length + 1));
  let out;
  if (isSvg) {
    const top = 360, row = 150;
    const svgBlocks = blocks.map((b, i) => {
      const delay = i * step, d = Math.max(200, duration - delay), y = top + i * row;
      return `<g class="block" style="animation-delay:${delay}ms;animation-duration:${d}ms">` +
        `<text class="label" x="64" y="${y}">${esc(b.label)}</text>` +
        `<text class="value" x="1136" y="${y}" text-anchor="end">${esc(b.value)}</text>` +
        `<line class="sep" x1="64" y1="${y + 28}" x2="1136" y2="${y + 28}" /></g>`;
    }).join("\n  ");
    out = tmpl.split("%%TITLE%%").join(esc(spec.title || ""))
      .split("%%BLOCKS%%").join(svgBlocks).split("%%ACCENT%%").join(accent)
      .split("%%MOTION_ANIM%%").join(kind).split("%%DURATION_MS%%").join(String(duration))
      .split("%%FPS%%").join(String(fps)).split("%%FRAMES%%").join(String(frames))
      .split("%%VIEWPORT%%").join(String(viewport)).split("%%ALT%%").join(escAttr(spec.alt || ""));
  } else {
    const htmlBlocks = blocks.map((b, i) => {
      const delay = i * step, d = Math.max(200, duration - delay);
      return `<div class="block" style="animation-delay:${delay}ms;animation-duration:${d}ms">` +
        `<span class="label">${esc(b.label)}</span><span class="value">${esc(b.value)}</span></div>`;
    }).join("\n      ");
    out = tmpl.split("%%TITLE%%").join(esc(spec.title || ""))
      .split("%%BLOCKS%%").join(htmlBlocks).split("%%ACCENT%%").join(accent)
      .split("%%MOTION_ANIM%%").join(kind).split("%%DURATION_MS%%").join(String(duration))
      .split("%%FPS%%").join(String(fps)).split("%%FRAMES%%").join(String(frames))
      .split("%%VIEWPORT%%").join(String(viewport));
  }
  const left = out.match(/%%[A-Z_]+%%/g);
  if (left) throw new Error("unresolved template token(s): " + left.join(", "));
  return out;
}
const spec = $('spec_ready').first().json.SPEC;
const specJson = $('spec_ready').first().json.SPEC_JSON;
const specDuration = Math.max(1000, Math.min(4000, (spec.motion && spec.motion.durationMs) || 3000));
const htmlT = $('download_html_template').first().json.output;
const svgT = $('download_svg_template').first().json.output;
const asset = (a, status) => ({
  ASSET_TYPE: a.ASSET_TYPE, RENDER_MODE: a.RENDER_MODE || '', FORMAT: a.FORMAT || '',
  STATUS: status, SPEC_JSON: specJson, PROMPT: '', CONTENT_TYPE: '', ERROR: '',
  DURATION_MS: '', FRAME_COUNT: '', WIDTH: '', HEIGHT: '',
});
const out = [];
for (const item of $('parse_registry').all()) {
  const a = item.json;
  if (a.STATUS === 'UNKNOWN' || a.STATUS === 'SKIPPED') {
    out.push({ json: asset(a, a.STATUS) });
    out[out.length - 1].json.ERROR = a.ERROR || '';
    continue;
  }
  if (a.AVAILABLE === false) {
    const r = asset(a, 'UNAVAILABLE');
    r.ERROR = a.UNAVAILABLE_REASON || ('unavailable: ' + a.ASSET_TYPE);
    out.push({ json: r });
    continue;
  }
  const r = asset(a, 'AUTHORED');
  let markup = '', markupKind = '';
  if (a.AUTHOR === 'spec_markup') {
    if (a.RENDER_MODE === 'animated') { markup = buildMarkup(htmlT, spec, a.FPS, a.FRAMES, a.VIEWPORT, false); markupKind = 'text/html'; }
    else if (a.RENDER_MODE === 'text') { markup = buildMarkup(svgT, spec, a.FPS, a.FRAMES, a.VIEWPORT, true); markupKind = 'image/svg+xml'; }
  }
  r.MARKUP = markup;
  r.CONTENT_TYPE = markupKind;
  if (a.RENDER_MODE === 'animated') {
    const fpsCap = Math.max(1, Math.min(12, Number(a.FPS) || 12));
    const frameCap = Math.max(1, Math.min(36, Number(a.FRAMES) || 36));
    r.VIEWPORT = String(Math.max(1, Math.min(1200, Number(a.VIEWPORT) || 1200)));
    r.DURATION_MS = String(specDuration);
    r.FRAME_COUNT = String(Math.max(1, Math.min(frameCap, Math.floor(specDuration * fpsCap / 1000))));
  }
  out.push({ json: Object.assign({}, a, r) });
}
return out;

