// gif type is assembled as GIF rather than falling back to it. A missing FORMAT keeps
// the original webp-then-gif order.
const webpCmd = "'" + img2webp + "' -loop 0 " + webpArgs.join(' ') + " -o out.webp";
const gifCmd = 'gm convert ' + gifArgs.join(' ') + ' out.gif';
const encoders = {
  gif: { want: gifCmd, F: 'out.gif', MIME: 'image/gif', other: webpCmd, oF: 'out.webp', oMIME: 'image/webp' },
  webp: { want: webpCmd, F: 'out.webp', MIME: 'image/webp', other: gifCmd, oF: 'out.gif', oMIME: 'image/gif' },
};
const pick = encoders[String(a.FORMAT || '').toLowerCase()] || encoders.webp;
const encoderCmd = [
  'if ' + pick.want + ' >/dev/null 2>&1; then F=' + pick.F + '; MIME=' + pick.MIME + ';',
  'elif ' + pick.other + ' >/dev/null 2>&1; then F=' + pick.oF + '; MIME=' + pick.oMIME + ';',
  'else exit 1; fi',
].join(' ');
const cmd = [
  'set -e',
  "cd '" + dir + "'",
  encoderCmd,
  "printf 'data:%s;base64,' \"$MIME\"",
  'base64 -w0 "$F"',
  "rm -rf '" + dir + "'",
  "rmdir '/home/node/.n8n-files/" + run + "' 2>/dev/null || true",
].join('\n');
return [{ json: { CMD: cmd, RUN_ID: run, ASSET_TYPE: asset } }];

